import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider } from "./contexts/AuthContext";
import { PrivateRoute, PublicRoute } from "./routes/PrivateRoute";
import { PermissionRoute } from "./routes/RoleRoute";
import LandingPage from "./pages/LandingPage";
import DashboardPage from "./pages/DashboardPage";
import UsersPage from "./pages/UsersPage";
import RolesPage from "./pages/RolesPage";

import "./App.css";

function App() {
  return (
    <Router>
      <AuthProvider>
        <Routes>
          {/* Ruta pública - Landing Page (incluye login) */}
          <Route
            path="/"
            element={
              <PublicRoute>
                <LandingPage />
              </PublicRoute>
            }
          />

          {/* Panel privado - el contenido se adapta según el rol */}
          <Route
            path="/dashboard"
            element={
              <PrivateRoute>
                <DashboardPage />
              </PrivateRoute>
            }
          />

          {/* Usuarios */}
          <Route
            path="/dashboard/usuarios"
            element={
              <PrivateRoute>
                <PermissionRoute requiredPermissions={["users.view"]}>
                  <UsersPage />
                </PermissionRoute>
              </PrivateRoute>
            }
          />

          {/* Roles y Permisos */}
          <Route
            path="/dashboard/roles"
            element={
              <PrivateRoute>
                <PermissionRoute requiredPermissions={["roles.view", "roles.manage"]}>
                  <RolesPage />
                </PermissionRoute>
              </PrivateRoute>
            }
          />

          {/* Ruta por defecto */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </AuthProvider>
    </Router>
  );
}

export default App;
